package httpapi

// The API's wire types, named.
//
// Everything an endpoint accepts or returns is a declared type here rather
// than an anonymous struct or a map[string]any assembled at the write site.
// That is not tidiness for its own sake: the OpenAPI document is generated by
// reflecting over these (routes.go), so a shape that exists only as a literal
// inside a handler is a shape the spec — and therefore the generated client —
// cannot describe. A map response used to mean the frontend guessed.

import (
	"encoding/json"
	"time"

	"apothecary/internal/account/auth"
	"apothecary/internal/engine"
	"apothecary/internal/flow"
	"apothecary/internal/flow/actionspec"
	"apothecary/internal/flow/reviewfile"
	"apothecary/internal/flow/signalspec"
	"apothecary/internal/platform/filestore"
	"apothecary/internal/ports/envport"
	"apothecary/internal/project/confstore"
	"apothecary/internal/project/kinds"
	"apothecary/internal/run"
	"apothecary/internal/run/event"
	"apothecary/internal/run/runinput"
	"apothecary/internal/skills"
	"apothecary/internal/skills/skillstore"
	"apothecary/internal/workspace/portrelay"
)

// --- errors -----------------------------------------------------------------

// ErrorResponse is the one error shape every endpoint uses. RunID is set on
// the 409 refusing a run on a ticket that already has an active one
// (engine.ErrTicketBusy): the run to open or abort. Tickets and ActiveRuns
// are set on the 409 refusing to delete a ticketsource integration whose
// tickets still mirror its issues: how many would be unlinked, and how many
// runs on them are still going (?unlink_tickets=1 confirms).
type ErrorResponse struct {
	Error      string `json:"error"`
	RunID      string `json:"run_id,omitempty"`
	Tickets    *int   `json:"tickets,omitempty"`
	ActiveRuns *int   `json:"active_runs,omitempty"`
}

// --- runs -------------------------------------------------------------------

// RunDetail is a run plus the tail of its event log (the run page's first
// paint; the SSE stream takes over from there).
type RunDetail struct {
	Run    run.View      `json:"run"`
	Events []event.Event `json:"events"`
}

// RunRef names a run the call just created or forked.
type RunRef struct {
	RunID string `json:"run_id"`
}

// RerunRequest re-runs a finished run's ticket as a NEW run: same ticket,
// fresh workspace. Every field is optional and overrides what the original
// used.
type RerunRequest struct {
	Flow          string   `json:"flow,omitempty"`
	Goal          string   `json:"goal,omitempty"`
	SourceBranch  string   `json:"source_branch,omitempty"`
	AttachmentIDs []string `json:"attachment_ids,omitempty"`
	// Params override the parameter values the original ran with.
	Params map[string]string `json:"params,omitempty"`
	// MR moves the rerun to another merge request ("" = the one the
	// original was started on, if it was).
	MR *runinput.MR `json:"mr,omitempty"`
	// Skillsets replace the original's (absent = the original's at their
	// latest version; an empty list = none).
	Skillsets []skills.Ref `json:"skillsets,omitempty"`
}

// StartRunRequest starts one attempt on a ticket.
type StartRunRequest struct {
	Flow          string   `json:"flow,omitempty"`
	Goal          string   `json:"goal,omitempty"`
	SourceBranch  string   `json:"source_branch,omitempty"`
	AttachmentIDs []string `json:"attachment_ids,omitempty"`
	// Params override the workshop's parameter bindings for this attempt.
	Params map[string]string `json:"params,omitempty"`
	// MR starts the run on a merge request someone opened, for a flow
	// whose runs are started on one (operates_on: merge_request).
	MR *runinput.MR `json:"mr,omitempty"`
	// Skillsets are the caller's skillsets to install into the workspace,
	// each at a version (seq 0 or absent = latest).
	Skillsets []skills.Ref `json:"skillsets,omitempty"`
}

// --- skills -----------------------------------------------------------------

// SkillFileRequest is one file of a skill, bytes base64-encoded. Mode is
// advisory: files under scripts/ and files sent executable install 0755,
// everything else 0644.
type SkillFileRequest struct {
	Path       string `json:"path"`
	ContentB64 string `json:"content_b64"`
	Mode       uint32 `json:"mode,omitempty"`
}

// SkillRequest is a skill's whole content: the name it installs under (must
// equal SKILL.md's frontmatter name) and every file, SKILL.md included.
type SkillRequest struct {
	Name  string             `json:"name"`
	Files []SkillFileRequest `json:"files"`
}

// SkillDetail is one skill with its file contents.
type SkillDetail struct {
	Skill    skillstore.Skill   `json:"skill"`
	Contents []SkillFileRequest `json:"contents"`
}

// SkillImportRequest names a public folder to import: a github.com or
// GitLab folder URL, or a link to a .tar.gz/.zip, with an optional
// subfolder inside it.
type SkillImportRequest struct {
	URL  string `json:"url"`
	Path string `json:"path,omitempty"`
}

// SkillsetRequest is a skillset's editable surface: its name, description
// and ordered members.
type SkillsetRequest struct {
	Name        string   `json:"name"`
	Description string   `json:"description,omitempty"`
	SkillIDs    []string `json:"skill_ids"`
}

// SkillsetRefreshResult is a refreshed skillset plus what the folder held
// that could not become a member.
type SkillsetRefreshResult struct {
	Skillset skillstore.Skillset `json:"skillset"`
	Warnings []string            `json:"warnings,omitempty"`
}

// WorkspaceLog is one byte range of a run's workspace log: Data runs from
// Start to End, Size is the log's length when it was read. Keeping up asks
// next from End; going back asks for what ends at Start. Ranges never split
// a character.
type WorkspaceLog struct {
	Data  string `json:"data"`
	Start int64  `json:"start"`
	End   int64  `json:"end"`
	Size  int64  `json:"size"`
}

// --- egress -----------------------------------------------------------------

// EgressDefaults is the built-in allowlist every project starts from.
type EgressDefaults struct {
	Domains []string `json:"domains"`
}

// EgressPolicy is the firewall policy in force for a run right now.
type EgressPolicy struct {
	Mode           string   `json:"mode"` // allowlist|denylist
	Domains        []string `json:"domains"`
	BlockedDomains []string `json:"blocked_domains"`
}

// EgressHostRequest unblocks one host for a live run.
type EgressHostRequest struct {
	Host string `json:"host"`
}

// EgressAllowResult reports the live unblock and whether it also stuck to the
// project (so future runs inherit it).
type EgressAllowResult struct {
	Allowed   string `json:"allowed"`
	Persisted bool   `json:"persisted"`
}

// EgressRuleRequest sets one host's rule for a run: allow it or force-block it.
type EgressRuleRequest struct {
	Host  string `json:"host"`
	Allow bool   `json:"allow"`
}

// EgressRuleResult mirrors the applied rule and whether it was persisted.
type EgressRuleResult struct {
	Host      string `json:"host"`
	Allow     bool   `json:"allow"`
	Persisted bool   `json:"persisted"`
}

// --- ports / editor / resources ---------------------------------------------

// RunPorts is what the run's workspace publishes: Ports are exposed through
// the relay, Observed are listeners the in-workspace scanner found and nobody
// has exposed yet.
type RunPorts struct {
	Ports    []portrelay.Exposure   `json:"ports"`
	Observed []envport.ObservedPort `json:"observed"`
}

// ObservedPortsRequest is the in-workspace scanner's listener snapshot.
type ObservedPortsRequest struct {
	Ports []envport.ObservedPort `json:"ports"`
}

// ExposePortRequest publishes one workspace port through the relay.
type ExposePortRequest struct {
	Port int `json:"port"`
}

// ExposedPort is the browsable URL a published port got.
type ExposedPort struct {
	Port int    `json:"port"`
	URL  string `json:"url"`
}

// EditorURL is where the workspace's code-server is reachable.
type EditorURL struct {
	URL string `json:"url"`
}

// RunResources is the rolling window of workspace samples behind the run
// page's graphs.
type RunResources struct {
	Samples []envport.ResourceSample `json:"samples"`
}

// --- pings ------------------------------------------------------------------

// RaisePingRequest is the ask_human shim's question (run-token auth).
type RaisePingRequest struct {
	Type     string `json:"type"` // clarification|blocker|permission
	Question string `json:"question"`
	Context  string `json:"context,omitempty"`
	// Fields are what it asks, in order (ACP's elicitation form); none is
	// one free-text answer.
	Fields    []event.Field `json:"fields,omitempty"`
	Artifact  string        `json:"artifact,omitempty"`  // legacy single workspace file
	Artifacts []string      `json:"artifacts,omitempty"` // workspace files to review
	// HoldMS is how long this request may hold for an answer, clamped to the
	// server's own limit; the caller long-polls the rest of the wait.
	HoldMS int `json:"hold_ms,omitempty"`
	// Key is the caller's idempotency key: a raise retried with the same key
	// returns the question the first one created.
	Key string `json:"key,omitempty"`
}

// PingHold is the answer, when one arrives inside the hold. A 204 means it
// did not, and the id in the X-Ping-ID header is how the caller re-polls.
type PingHold struct {
	PingID string `json:"ping_id"`
	// Text is the composed answer, rendered server-side so the tool return and
	// a resumed stage's message say the same thing; Answer (accept|decline),
	// Feedback and Content are the raw fields behind it — what a harness's
	// own question (an ACP elicitation) is answered with.
	Text      string         `json:"text"`
	Answer    string         `json:"answer"`
	Feedback  string         `json:"feedback,omitempty"`
	Content   map[string]any `json:"content,omitempty"`
	Artifacts []string       `json:"artifacts,omitempty"` // workspace paths of the human's files
}

// AnswerPingRequest answers a question: approve|reject for a gate, accept
// with the form's content or decline with a note for a form.
type AnswerPingRequest struct {
	Answer   string `json:"answer"`
	Feedback string `json:"feedback,omitempty"`
	// Content is an accepted form's values, by field id: a string, number,
	// boolean, or (array field) a list of option ids.
	Content       map[string]any `json:"content,omitempty"`
	AttachmentIDs []string       `json:"attachment_ids,omitempty"`
	// Review is the comments on the files the ping shows, each on one of
	// them (feedback is then the review's summary): on its lines, or on the
	// whole file — always, on an image.
	Review []event.ReviewComment `json:"review,omitempty"`
	// Curated is what the person made of each review document the gate
	// shows (a review_threads or review_replies file), by path: decisions
	// over the document as shown — which items are posted (all, unless
	// unpicked) and how they read. Approve posts the curated document;
	// reject keeps the decisions on the record for the redo.
	Curated map[string]reviewfile.Curation `json:"curated,omitempty"`
}

// CurationView is a question's review documents, decoded as the gate showed
// them (their raise-time snapshots): what the curation page lists, item by
// item, and the threads beside them when the gate showed an mr_threads file.
type CurationView struct {
	Documents []CurationDocument `json:"documents"`
	// Threads is the first mr_threads file shown: the conversations the
	// notes and replies refer to.
	Threads *reviewfile.Threads `json:"threads,omitempty"`
}

// CurationDocument is one shown file of a review type, decoded. Captured
// false, or Error, means it cannot be curated — only approved as written.
type CurationDocument struct {
	Path     string             `json:"path"`
	Type     string             `json:"type"`
	Captured bool               `json:"captured"`
	Error    string             `json:"error,omitempty"`
	Review   *reviewfile.Review `json:"review,omitempty"`
	Replies  []reviewfile.Reply `json:"replies,omitempty"`
}

// AnswerAccepted confirms an answer was recorded.
type AnswerAccepted struct {
	Status string `json:"status"` // answered
}

// PingFile is one file attached to a ping, as it can be served now: captured
// means the engine holds an immutable snapshot of what the human was shown.
type PingFile struct {
	Path       string `json:"path"`
	Captured   bool   `json:"captured"`
	SnapshotID string `json:"snapshot_id,omitempty"`
	Mime       string `json:"mime,omitempty"`
	Size       int64  `json:"size,omitempty"`
	// Type is the file's port type when it is a structured one (a review
	// to curate, the threads beside it); absent for a plain document.
	Type string `json:"type,omitempty"`
}

// PingFiles is a ping's payload: its files (first is the primary reviewed
// document) and its link, if it carried one instead.
type PingFiles struct {
	Files []PingFile `json:"files"`
	Link  string     `json:"link,omitempty"`
}

// --- files ------------------------------------------------------------------

// Uploaded is what an upload produced, in request order.
type Uploaded struct {
	Attachments []filestore.Attachment `json:"attachments"`
}

// AttachmentList is a set of human-given files.
type AttachmentList struct {
	Attachments []filestore.Attachment `json:"attachments"`
}

// RunFiles is everything filed under a run: what humans gave it, and what the
// engine captured out of its workspace.
type RunFiles struct {
	Attachments []filestore.Attachment `json:"attachments"`
	Snapshots   []filestore.Snapshot   `json:"snapshots"`
}

// --- config plane -----------------------------------------------------------

// IntegrationRequest creates an integration (a configured instance of a kind).
type IntegrationRequest struct {
	Port    string            `json:"port"`
	Kind    string            `json:"kind"`
	Name    string            `json:"name"`
	Config  map[string]any    `json:"config,omitempty"`
	Secrets map[string]string `json:"secrets,omitempty"`
}

// IntegrationUpdate changes one. Secrets merge: a present key replaces, ""
// deletes, an absent key keeps what is stored.
type IntegrationUpdate struct {
	Name    string            `json:"name"`
	Config  map[string]any    `json:"config,omitempty"`
	Secrets map[string]string `json:"secrets,omitempty"`
}

// TestResult is an integration's credential check.
type TestResult struct {
	OK    bool   `json:"ok"`
	Error string `json:"error,omitempty"`
	// Warnings: what the test could not verify (a credential with no
	// zero-token probe, a provider out of reach). Not a failure.
	Warnings []string `json:"warnings,omitempty"`
}

// PreflightResult is a project's readiness: every check reports on its own so
// the UI can name exactly what is missing.
type PreflightResult struct {
	OK    bool                   `json:"ok"`
	Steps []engine.PreflightStep `json:"steps"`
}

// RebuildRequest recreates a run's workspace container in place. NoCache
// rebuilds the image from scratch: the build cache is keyed by what the build
// reads, so a changed Dockerfile already rebuilds itself — this is for what a
// cache key cannot see, like a floating base tag that moved upstream.
type RebuildRequest struct {
	NoCache bool `json:"no_cache,omitempty"`
}

// BuildCacheInfo is the project's devcontainer build cache: what it holds, and
// whether the provisioner keeps one at all. It is what makes a second run of a
// project fast, and the one piece of derived state worth a delete button.
type BuildCacheInfo struct {
	Available bool  `json:"available"`
	Bytes     int64 `json:"bytes"`
}

// EnvCheckRequest starts a throwaway provision to prove a project's workspace
// config actually builds. Keep leaves the container up for inspection.
type EnvCheckRequest struct {
	Keep bool `json:"keep"`
}

// EnvCheckRef names the check to poll.
type EnvCheckRef struct {
	CheckID string `json:"check_id"`
}

// --- flows ------------------------------------------------------------------

// CreateFlowRequest adds a flow document. Layout is the editor's node
// positions, opaque to the engine.
type CreateFlowRequest struct {
	Name   string          `json:"name"`
	YAML   string          `json:"yaml"`
	Layout json.RawMessage `json:"layout,omitempty"`
}

// UpdateFlowRequest replaces one.
type UpdateFlowRequest struct {
	YAML   string          `json:"yaml"`
	Layout json.RawMessage `json:"layout,omitempty"`
}

// CopyFlowRequest clones a flow — one of a project's, or a compiled-in
// template — into a project. Name renames the copy; empty keeps the source's
// name. The copy is a new document with its own history — editing it never
// reaches back to the original.
type CopyFlowRequest struct {
	ToProjectID string `json:"to_project_id"`
	Name        string `json:"name,omitempty"`
}

// FlowBindingRequest is a project's values for a flow's parameters: every
// key a parameter the flow declares (the engine-known names included), every
// value one it accepts; an empty value unbinds that parameter. The whole
// binding is replaced, and one left with no values is removed.
type FlowBindingRequest struct {
	Params map[string]string `json:"params"`
}

// AutomationRequest creates or replaces an automation: a way a run begins
// without a person pressing Start. kind is tracker_query (poll source_id
// with query, import what it finds, one run each), cron (schedule, five
// fields in UTC, a new run of ticket_id each firing) or merge_request (watch
// repo's open merge requests, a run on each one someone else opened, once).
// flow (one whose operates_on fits: merge_request for a merge_request
// automation, ticket otherwise) + params say what each firing creates.
// enabled defaults to true.
type AutomationRequest struct {
	Name     string            `json:"name"`
	Kind     string            `json:"kind"`
	SourceID string            `json:"source_id,omitempty"`
	Query    string            `json:"query,omitempty"`
	Schedule string            `json:"schedule,omitempty"`
	TicketID string            `json:"ticket_id,omitempty"`
	Repo     string            `json:"repo,omitempty"`
	Flow     string            `json:"flow"`
	Params   map[string]string `json:"params,omitempty"`
	Enabled  *bool             `json:"enabled,omitempty"`
}

// StartPhaseRequest starts a phase by hand. Subject is the checkout whose
// merge request the phase acts on; empty picks the run's single open one, or
// none.
type StartPhaseRequest struct {
	Subject string `json:"subject,omitempty"`
}

// ValidateFlowRequest checks a flow document without saving it. Params, when
// given, are bound values to validate it with too (a workshop's bindings): a
// value that breaks a rule is reported like any error.
type ValidateFlowRequest struct {
	YAML   string            `json:"yaml"`
	Params map[string]string `json:"params,omitempty"`
}

// FlowValidation is the verdict. On failure Errors says why and the rest is
// absent; on success the parsed shape comes back for the editor to render,
// with what its runs are started on, the document's parameters (declared and
// read where) and its phases summarized with the defaults applied — so the
// editor never re-derives a start policy or a max.
type FlowValidation struct {
	OK         bool            `json:"ok"`
	Errors     []string        `json:"errors,omitempty"`
	Name       string          `json:"name,omitempty"`
	Hash       string          `json:"hash,omitempty"`
	OperatesOn string          `json:"operates_on,omitempty"`
	Stages     int             `json:"stages,omitempty"`
	Agents     int             `json:"agents,omitempty"`
	Doc        *flow.Doc       `json:"doc,omitempty"`
	Warnings   []string        `json:"warnings,omitempty"`
	Parameters []flow.Param    `json:"parameters,omitempty"`
	Refs       []flow.ParamRef `json:"refs,omitempty"`
	Phases     []PhaseSummary  `json:"phases,omitempty"`
}

// PhaseSummary is one phase of a flow — its main chain, a watcher or an
// outcome (Kind) — with its wait point's effective values (FLOWLANG §1):
// what opens it, the start policy, the debounce, the run bound, how an
// outcome ends the run (Then) and whether its runs act on one merge
// request.
type PhaseSummary struct {
	ID          string `json:"id"`
	Description string `json:"description,omitempty"`
	Kind        string `json:"kind"`
	// Signal opens the phase: manual, or one the engine observes; empty for
	// the main chain, which runs when the run is started.
	Signal   string `json:"signal"`
	Start    string `json:"start"`
	QuietFor string `json:"quiet_for,omitempty"`
	Max      int    `json:"max"`
	Then     string `json:"then,omitempty"`
	Subject  bool   `json:"subject,omitempty"`
	Stages   int    `json:"stages"`
}

// phaseSummaries renders a parsed flow's phases.
func phaseSummaries(f *flow.Flow) []PhaseSummary {
	out := make([]PhaseSummary, 0, len(f.Phases))
	for i := range f.Phases {
		ph := &f.Phases[i]
		ps := PhaseSummary{ID: ph.ID, Description: ph.Description, Kind: string(ph.Kind), Signal: ph.On.Signal, Start: string(ph.On.Start),
			Max: ph.On.Max, Then: ph.Then, Subject: ph.HasSubject(), Stages: ph.Last - ph.First + 1}
		if ph.On.QuietFor > 0 {
			ps.QuietFor = ph.On.QuietFor.String()
		}
		out = append(out, ps)
	}
	return out
}

// --- registries -------------------------------------------------------------

// KindList is every port kind this build carries, with the fields each needs.
type KindList []kinds.Descriptor

// ActionList is the action registry an `action` stage may name.
type ActionList []actionspec.Action

// SignalList is the signal registry a `wait` stage or a gate's auto-answer may
// name.
type SignalList []signalspec.Signal

// --- channels ---------------------------------------------------------------

// ChannelRequest adds a notification channel. The kind picks the driver; the
// remaining keys are that driver's own config (secrets are masked on read).
type ChannelRequest map[string]any

// --- accounts (TODO 25) -----------------------------------------------------

// AuthStatus is what the UI asks before anything else.
type AuthStatus struct {
	// SetupRequired: no account exists yet; the setup page is the only page.
	SetupRequired bool `json:"setup_required"`
	// Methods are the authentication methods this instance can verify.
	Methods []string `json:"methods"`
}

// SetupRequest claims a fresh instance: its first account, an admin.
type SetupRequest struct {
	Handle   string `json:"handle"`
	Email    string `json:"email"`
	Name     string `json:"name,omitempty"`
	Password string `json:"password"`
}

// LoginRequest is one attempt to sign in: the method (password when
// omitted), the account (handle or email) and the proof (the password).
type LoginRequest struct {
	Method string `json:"method,omitempty"`
	Login  string `json:"login"`
	Proof  string `json:"proof"`
}

// Me is the signed-in user, with the kinds of method they can sign in by.
type Me struct {
	User    auth.User `json:"user"`
	Methods []string  `json:"methods"`
}

// ProfileRequest changes one's own handle, email or name (absent = keep).
type ProfileRequest struct {
	Handle string `json:"handle,omitempty"`
	Email  string `json:"email,omitempty"`
	Name   string `json:"name,omitempty"`
}

// PasswordChangeRequest changes one's own password.
type PasswordChangeRequest struct {
	Current  string `json:"current"`
	Password string `json:"password"`
}

// TokenRequest mints a personal API token.
type TokenRequest struct {
	Name      string     `json:"name"`
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
}

// TokenCreated carries the secret, the one time it is ever shown.
type TokenCreated struct {
	Token  auth.Token `json:"token"`
	Secret string     `json:"secret"`
}

// SSHKeyRequest registers a public key on one's account: the contents of a
// .pub file, with an optional name (the key's comment, else its type,
// otherwise).
type SSHKeyRequest struct {
	Name      string `json:"name,omitempty"`
	PublicKey string `json:"public_key"`
}

// RunSSH is how to reach a run's workspace over SSH (the run page's "Open in
// VS Code" and "ssh" rows). Enabled false means the instance runs no SSH
// door (Reason says so). Host and Port are the door's advertised address;
// User the name to log in as (the workspace); Path the folder an editor
// opens ("" when the sidecar could not say); Fingerprint and HostKey the
// door's host key, to verify on first connect; Command the ssh command line;
// VSCodeURL the vscode:// link; Keys how many SSH keys the caller has
// registered (0: nothing will let them in yet).
type RunSSH struct {
	Enabled     bool   `json:"enabled"`
	Reason      string `json:"reason,omitempty"`
	Host        string `json:"host,omitempty"`
	Port        int    `json:"port,omitempty"`
	User        string `json:"user,omitempty"`
	Path        string `json:"path,omitempty"`
	Fingerprint string `json:"fingerprint,omitempty"`
	HostKey     string `json:"host_key,omitempty"`
	Command     string `json:"command,omitempty"`
	VSCodeURL   string `json:"vscode_url,omitempty"`
	// Extensions are the VS Code extension ids the workspace's own editor
	// runs (the definition's ∪ the project's): what a desktop editor over
	// SSH can carry over (remote.defaultExtensionsIfInstalledLocally).
	Extensions []string `json:"extensions,omitempty"`
	Keys       int      `json:"keys"`
}

// UserCreateRequest is an admin creating an account.
type UserCreateRequest struct {
	Handle   string `json:"handle"`
	Email    string `json:"email"`
	Name     string `json:"name,omitempty"`
	Password string `json:"password"`
	Admin    bool   `json:"admin,omitempty"`
}

// UserUpdateRequest is an admin changing an account: profile fields
// (absent = keep), the admin flag, and whether it is disabled.
type UserUpdateRequest struct {
	Handle   string `json:"handle,omitempty"`
	Email    string `json:"email,omitempty"`
	Name     string `json:"name,omitempty"`
	Admin    *bool  `json:"admin,omitempty"`
	Disabled *bool  `json:"disabled,omitempty"`
}

// PasswordResetRequest is an admin setting an account's password.
type PasswordResetRequest struct {
	Password string `json:"password"`
}

// LimitsInfo is the deployment's capacity: -1 means no cap.
type LimitsInfo struct {
	MaxConcurrentRuns int `json:"max_concurrent_runs"`
	MaxEnvironments   int `json:"max_environments"`
}

// Compile-time proof that the config-plane types the spec names are the ones
// the handlers actually write.
var (
	_ = confstore.Project{}
	_ = confstore.Settings{}
)
